/usr/bin/env -i PATH="/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin" LC_ALL=C.UTF-8 LANG=C.UTF-8 python3 -I -c 'import concurrent.futures, json, os, shutil, stat, subprocess, sys
from pathlib import Path

SAFE_PATH = "/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin"

def fail(reason):
  print(json.dumps({"decision": "continue", "reason": reason}))
  raise SystemExit(0)

try:
  cwd = Path.cwd().resolve()
  root = cwd.parent if cwd.name == ".agents" else cwd
  if not (root / ".git").exists():
    fail("Repository root not found.")
  git_bin = shutil.which("git", path=SAFE_PATH)
  node_bin = shutil.which("node", path=SAFE_PATH)
  if not git_bin or not node_bin:
    fail("Required git or node binary missing from safe PATH.")
  g = subprocess.run(
    [git_bin, "-c", "core.fsmonitor=false", "-c", "core.hooksPath=/dev/null", "-C", str(root), "show", "origin/main:scripts/check_style.py"],
    capture_output=True,
    check=False,
  )
  if g.returncode != 0 or not g.stdout:
    fail("Failed to load origin/main style checker.")
  p = subprocess.run(
    [sys.executable, "-I", "-"],
    input=g.stdout,
    capture_output=True,
    cwd=str(root),
    check=False,
  )
  if p.returncode != 0:
    fail("Style check failed.")
  files = []
  for rel in ("web/strategy-switch-console/application", "tests"):
    base = root / rel
    try:
      st_b = base.lstat()
    except OSError:
      fail("Expected source directory missing.")
    if not stat.S_ISDIR(st_b.st_mode) or stat.S_ISLNK(st_b.st_mode):
      fail("Source directory must be a real directory.")
    for dirpath, dirnames, filenames in os.walk(base, followlinks=False):
      kept = []
      for d in dirnames:
        if d in ("node_modules", ".git"):
          continue
        dp = Path(dirpath) / d
        try:
          st_d = dp.lstat()
        except OSError:
          continue
        if stat.S_ISDIR(st_d.st_mode) and not stat.S_ISLNK(st_d.st_mode):
          kept.append(d)
      dirnames[:] = kept
      for f in filenames:
        if not f.endswith((".js", ".mjs")):
          continue
        fp = Path(dirpath) / f
        try:
          st_f = fp.lstat()
        except OSError:
          fail("Failed to stat JS file.")
        if stat.S_ISLNK(st_f.st_mode):
          continue
        if not stat.S_ISREG(st_f.st_mode):
          fail("Unexpected non-regular JS file.")
        files.append(str(fp))
  if not files:
    fail("No JS files discovered for syntax validation.")
  def chk(path):
    return subprocess.run([node_bin, "--check", path], capture_output=True, check=False).returncode
  with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:
    if any(code != 0 for code in ex.map(chk, files)):
      fail("JavaScript syntax validation failed.")
  print(json.dumps({"decision": "allow"}))
except SystemExit:
  raise
except Exception:
  print(json.dumps({"decision": "continue", "reason": "Stop hook validation failed."}))'
